ALTER TABLE users ADD COLUMN google_id TEXT;
ALTER TABLE users ADD COLUMN email_verified INTEGER NOT NULL DEFAULT 0 CHECK(email_verified IN (0,1));
ALTER TABLE users ADD COLUMN avatar_url TEXT;
ALTER TABLE users ADD COLUMN role TEXT NOT NULL DEFAULT 'analyst' CHECK(role IN ('admin','analyst','viewer'));
ALTER TABLE users ADD COLUMN email_mfa_enabled INTEGER NOT NULL DEFAULT 0 CHECK(email_mfa_enabled IN (0,1));
ALTER TABLE users ADD COLUMN transaction_emails INTEGER NOT NULL DEFAULT 1 CHECK(transaction_emails IN (0,1));
ALTER TABLE users ADD COLUMN product_emails INTEGER NOT NULL DEFAULT 0 CHECK(product_emails IN (0,1));
ALTER TABLE users ADD COLUMN onboarding_completed INTEGER NOT NULL DEFAULT 0 CHECK(onboarding_completed IN (0,1));
ALTER TABLE users ADD COLUMN terms_accepted_at TEXT;
ALTER TABLE users ADD COLUMN terms_version TEXT;
CREATE UNIQUE INDEX users_google_id ON users(google_id) WHERE google_id IS NOT NULL;
UPDATE users SET email_verified=1,terms_accepted_at=created_at,terms_version='2026-11-24' WHERE email='demo@fintrack.local';
CREATE TABLE auth_tokens(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,purpose TEXT NOT NULL CHECK(purpose IN ('verify','reset','set')),token_hash TEXT NOT NULL UNIQUE,expires_at INTEGER NOT NULL,consumed_at INTEGER,created_at INTEGER NOT NULL);
CREATE INDEX auth_tokens_lookup ON auth_tokens(user_id,purpose,consumed_at);
CREATE TABLE sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at INTEGER NOT NULL,last_seen_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,revoked_at INTEGER,stay_logged_in INTEGER NOT NULL DEFAULT 0,mfa_verified_at INTEGER);
CREATE INDEX sessions_owner ON sessions(user_id,revoked_at);
CREATE TABLE refresh_tokens(token_hash TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL,consumed_at INTEGER,created_at INTEGER NOT NULL);
CREATE INDEX refresh_session ON refresh_tokens(session_id);
CREATE TABLE mfa_challenges(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,purpose TEXT NOT NULL CHECK(purpose IN ('login','enable')),session_id TEXT REFERENCES sessions(id) ON DELETE CASCADE,code_hash TEXT NOT NULL,expires_at INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,consumed_at INTEGER,last_sent_at INTEGER NOT NULL,stay_logged_in INTEGER NOT NULL DEFAULT 0);
CREATE INDEX mfa_owner ON mfa_challenges(user_id,purpose,consumed_at);
